-- Generated by `chainindex dbt` from chains/ethereum.yaml and abis/UniswapV3Pool.json. Do not edit: change the chain file or ABI and regenerate.
-- IncreaseObservationCardinalityNext(uint16,uint16)
{{ config(
    materialized='view',
    schema='events_ethereum',
    alias='uniswap_v3_pool__increase_observation_cardinality_next',
    tags=['chains', 'chain_ethereum'],
) }}

select
    toUInt64(1) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    toUInt16(reinterpretAsUInt256(reverse(unhex(substring(data, 3, 64))))) as observation_cardinality_next_old,
    toUInt16(reinterpretAsUInt256(reverse(unhex(substring(data, 67, 64))))) as observation_cardinality_next_new
from {{ source('chain_ethereum', 'logs') }}
where topic0 = '0xac49e518f90a358f652e4400164f05a5d8f7e35e7747279bc3a93dbf584e125a'
  and address in (select address from {{ ref('ethereum__contracts') }} where contract = 'uniswap_v3_pool')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_ethereum', 'orphaned_blocks') }}
  )
